import{_ as s,C as o,o as n,c as r,j as t,a as i,E as d,a2 as h}from"./chunks/framework.CGSzHL4z.js";const w=JSON.parse('{"title":"Why AcesMotion","description":"","frontmatter":{},"headers":[],"relativePath":"guide/why.md","filePath":"guide/why.md","lastUpdated":1792713747000}'),l={name:"guide/why.md"};function c(m,e,p,u,y,f){const a=o("Screenshot");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"why-acesmotion",tabindex:"-1"},[i("Why AcesMotion "),t("a",{class:"header-anchor",href:"#why-acesmotion","aria-label":'Permalink to "Why AcesMotion"'},"​")],-1)),d(a,{name:"cover",caption:"One scene with two rigs, two cameras, screen effects and a marker, on one Timeline."}),e[1]||(e[1]=h('<h2 id="why-i-made-it" tabindex="-1">Why I made it <a class="header-anchor" href="#why-i-made-it" aria-label="Permalink to &quot;Why I made it&quot;">​</a></h2><p>I kept running into the same two problems. A Roblox animation plays the same way every time: it can&#39;t know where the enemy is standing, so a punch keyed for a target two studs away hits air when the target is at four, and a fireball flies exactly as far as you keyed it. It also animates one rig&#39;s joints, and the moments that make a game feel good almost always involve more than one rig. A grab and slam has two characters, a camera shake, a dust burst and a sound that has to land on the impact frame.</p><p>None of that fits in a Roblox animation, so every ability turned into the same patchwork: an animation for the attacker, another for the victim, <code>task.wait(0.42)</code> to guess when the hit lands, a script to move the camera, another to emit the particles, and a prayer that it all still lines up after you change one keyframe. Then you upload, and the animation only works in games the owner can use.</p><p>I wanted animations that fit the game they play in, with everything the player sees on one Timeline, so I built AcesMotion.</p><h2 id="the-frustrations-it-fixes" tabindex="-1">The frustrations it fixes <a class="header-anchor" href="#the-frustrations-it-fixes" aria-label="Permalink to &quot;The frustrations it fixes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>The frustration</th><th>What AcesMotion does</th></tr></thead><tbody><tr><td>An attack plays the same path wherever the target is</td><td>Motion Warp bends the path so a punch, a throw or a projectile lands where the target really is. You animate the trip once and the game fits it to any range.</td></tr><tr><td>A scene is built around the objects you made it with</td><td>Actors are roles. Your game passes in the characters, or a role fills itself with the local player, the nearest player, the camera or a tagged object.</td></tr><tr><td>Aiming a head or a camera at something that moves takes your own code</td><td>Constraints (Track To, Damped Track, Lock, Floor, Limit Rotation and more) and drivers (Distance, Speed, Copy, Property) run live in game, on whoever plays each role.</td></tr><tr><td>A shake or a flicker means dozens of hand-placed keys</td><td>Generators (Shake, Wiggle, Oscillate, Flicker, Recoil and more) add motion without keys, seeded so every player sees the same thing.</td></tr><tr><td>One rig at a time, so scenes are impossible</td><td>A scene holds any number of actors: rigs, models, parts, cameras, any instance.</td></tr><tr><td>VFX, lights and cameras can&#39;t be animated</td><td>Property tracks animate any property of any instance, call keys run <code>Emit()</code> and <code>Play()</code>, and action tracks hold events and custom code.</td></tr><tr><td>Timing a hit means guessing with <code>task.wait</code></td><td>Markers and Event blocks fire signals at the exact frame, on the server too.</td></tr><tr><td>Sounds live outside the animation</td><td>Sound bars show waveforms and have trims, fades and loops, and keys snap to the loud hits.</td></tr><tr><td>Few curve tools</td><td>The curve editor has Bezier keys, tangent modes, an Ease view, saved presets, an Euler filter and a quaternion mode.</td></tr><tr><td>Undo forgets poses</td><td>Every edit, poses included, is one Studio undo step.</td></tr><tr><td>Shortening an animation deletes keys</td><td>Retiming scales keys, and inserting or removing time shifts them.</td></tr><tr><td>Animations must be uploaded and are owner-locked</td><td>The runtime plays scenes straight from data, so there is no upload and no ownership error.</td></tr><tr><td>Multiplayer cutscenes need custom networking</td><td><code>PlayForAll</code> plays a scene for every player, in sync with the server clock, late joiners included.</td></tr></tbody></table><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><ul><li>The plugin previews with the same engine code your game runs, byte for byte, so what you see in Studio is what plays.</li><li>It uses Studio&#39;s own colours and spacing, its shortcuts stay clear of Studio&#39;s, and every button has a tooltip.</li><li>AcesMotion never rewrites your joints, and closing a scene puts every stand-in back at rest.</li><li>A scene is one folder in your place that holds its cast, tracks, markers, sounds and cameras.</li></ul>',8))])}const k=s(l,[["render",c]]);export{w as __pageData,k as default};
